import os, sys, json, re
import numpy as np, pandas as pd
import statsmodels.api as sm
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE)
from docbuilder import Doc, fa, num, pval, S, LRI, PDI
import figlib as fl
from figlib import Diagram
from refs import LAT, FA, CITE, apa_latin

BASE = os.path.join(HERE, "..", "paper1"); OUT = os.path.join(BASE, "output"); os.makedirs(OUT, exist_ok=True)
R = json.load(open(os.path.join(OUT, "results_paper1.json"), encoding="utf-8"))
P, IND, REL, SEM, CFA = R["paths"], R["indirect"], R["rel"], R["sem"], R["cfa"]
d = Doc()
cited = set()

def K(key, paren=False):
    cited.add(key); fa_n, en_n, yr = CITE[key]
    if en_n is None: return f"({fa_n}، {yr})" if paren else f"{fa_n} ({yr})"
    mark = "" if en_n in d.seen else f"[[fn:{en_n}]]"; d.seen.add(en_n)
    return f"({fa_n}{mark}، {yr})" if paren else f"{fa_n}{mark} ({yr})"
def KK(*keys):
    parts = []
    for key in keys:
        cited.add(key); fa_n, en_n, yr = CITE[key]
        mark = "" if (en_n is None or en_n in d.seen) else f"[[fn:{en_n}]]"
        if en_n: d.seen.add(en_n)
        parts.append(f"{fa_n}{mark}، {yr}")
    return "(" + "؛ ".join(parts) + ")"
def T(fa_term, en_term):
    mark = "" if en_term in d.seen else f"[[fn:{en_term}]]"; d.seen.add(en_term); return f"{fa_term}{mark}"
f2 = lambda x: fa(f"{x:.2f}"); f3 = lambda x: fa(f"{x:.3f}"); F1 = lambda x: fa(f"{x:.1f}"); F0 = lambda x: fa(f"{x:.0f}")
def ptxt(p): return pval(p)
def coef(k, std=True): return num(P[k]["beta" if std else "b"], 2)
def zt(k): return S(f"z = {P[k]['z']:.2f}")
def stat(k): return f"{S('β = ' + format(P[k]['beta'], '.2f'))}، {zt(k)}، {ptxt(P[k]['p'])}"
def ci(k, std=False): v = IND[k]; return f"[{num(v['lo'], 3)}، {num(v['hi'], 3)}]"
def sig(p): return "∗∗∗" if p < .001 else "∗∗" if p < .01 else "∗" if p < .05 else "ns"

# ---------- پیش‌بررسی منطقی نتایج (اطمینان از هم‌خوانی متن با نتایج)
assert P["FOMO~SME"]["p"] < .001 and P["HRD~FOMO"]["p"] < .001 and P["IDQ~HRD"]["p"] < .001 and P["HRD~SME"]["p"] < .01
assert P["HRD~INT"]["p"] < .05 and P["HRD~INT"]["b"] < 0 and P["IDQ~AIU"]["p"] < .001
assert IND["ind_SME_FOMO_HRD_IDQ_mean"]["sig"] and IND["imm"]["sig"] and IND["imm"]["est"] > 0
assert R["cfa"]["cfi"] >= .95 and R["cfa"]["rmsea"] <= .06 and R["cfa"]["srmr"] <= .08

